import fs from "node:fs";
import path from "node:path";
const root = process.argv[2], req = process.argv[3];
const out = { total: 0, to_rv: 0, rv_pass: 0, rv_pass_naming_req: [], rv_any_naming_req: [], unparsable: [] };
for (const run of fs.readdirSync(path.join(root, "handoffs"))) {
  const d = path.join(root, "handoffs", run);
  if (!fs.statSync(d).isDirectory()) continue;
  for (const f of fs.readdirSync(d)) {
    if (!f.endsWith(".json")) continue;
    const rel = `handoffs/${run}/${f}`;
    let j; try { j = JSON.parse(fs.readFileSync(path.join(d, f), "utf8")); } catch { out.unparsable.push(rel); continue; }
    if (!j || typeof j !== "object" || Array.isArray(j) || !("to_agent" in j)) continue;
    out.total++;
    if (j.to_agent !== "RELEASE-VALIDATOR") continue;
    out.to_rv++;
    const ids = j.context?.requirement_ids ?? [];
    const pass = j.result?.verdict === "PASS";
    if (pass) out.rv_pass++;
    if (ids.includes(req)) { out.rv_any_naming_req.push({ rel, status: j.status, verdict: j.result?.verdict ?? null }); if (pass) out.rv_pass_naming_req.push(rel); }
  }
}
console.log(JSON.stringify(out, null, 1));
console.log("COUNT rv PASS naming", req, "=", out.rv_pass_naming_req.length);

