import fs from "node:fs"; import path from "node:path";
const root=process.argv[2];
const y=fs.readFileSync(path.join(root,"docs/requirements.yaml"),"utf8").split("\n");
const reqs=[];let cur=null;
for(const l of y){let m=l.match(/^  - id: (REQ-\d+)$/);if(m){cur={id:m[1]};reqs.push(cur);continue}
 m=l.match(/^    status: (\S+)\s*(#.*)?$/);if(m&&cur&&!cur.status){cur.status=m[1];cur.comment=m[2]||""}}
const rv={};// req -> list of PASS RV handoffs
for(const r of fs.readdirSync(path.join(root,"handoffs"))){const d=path.join(root,"handoffs",r);if(!fs.statSync(d).isDirectory())continue;
 for(const f of fs.readdirSync(d)){if(!f.endsWith(".json"))continue;let j;try{j=JSON.parse(fs.readFileSync(path.join(d,f),"utf8"))}catch{continue}
  if(j.to_agent==="RELEASE-VALIDATOR"&&j.result?.verdict==="PASS")for(const id of j.context?.requirement_ids??[])(rv[id]??=[]).push(`handoffs/${r}/${f}`)}}
let done=0,noRV=[],missingCited=[];
for(const q of reqs){if(q.status!=="done")continue;done++;
 if(!(rv[q.id]?.length))noRV.push(q.id);
 for(const m of (q.comment||"").matchAll(/handoffs\/[A-Za-z0-9._\/-]+\.json/g))if(!fs.existsSync(path.join(root,m[0])))missingCited.push(`${q.id} -> ${m[0]}`)}
console.log("requirements:",reqs.length,"status done:",done);
console.log("done without any RV PASS handoff naming them:",JSON.stringify(noRV));
console.log("cited handoff paths in done status comments that do not exist:",JSON.stringify(missingCited));
